namespace sv_f0f5c5db80134f0285f6516058eb4f72.Services;

public enum ThemeMode { Light, Dark, System }

/// <summary>
/// Scoped service that holds theme state for the current circuit (interactive)
/// or the current request (static SSR). Interactive components subscribe to
/// OnThemeChanged to re-render when another component mutates the state.
/// </summary>
public sealed class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnThemeChanged;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnThemeChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnThemeChanged?.Invoke();
    }

    /// <summary>
    /// Bulk-set from cookie values without raising events (used during
    /// initialisation so we don't trigger re-renders before first render).
    /// </summary>
    public void InitialiseFrom(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
    }
}

// Applies theme attributes to <html> and persists choices in cookies.
// Called from both static SSR (inline script) and interactive components
// via JS interop so the UI updates immediately regardless of render mode.

export function applyTheme(theme, accentColor) {
    const root = document.documentElement;
    root.setAttribute("data-bs-theme", resolveTheme(theme));
    root.style.setProperty("--app-accent", accentColor);
    setCookie("app-theme", theme, 365);
    setCookie("app-accent", accentColor, 365);
}

function resolveTheme(theme) {
    if (theme === "System") {
        return window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "dark" : "light";
    }
    return theme.toLowerCase();
}

function setCookie(name, value, days) {
    const expires = new Date(Date.now() + days * 864e5).toUTCString();
    document.cookie = `${name}=${encodeURIComponent(value)};expires=${expires};path=/;SameSite=Lax`;
}

@page "/settings"
@rendermode InteractiveServer
@using sv_f0f5c5db80134f0285f6516058eb4f72.Services
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Theme</label>
    <div class="btn-group d-block" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            var isActive = mode == ThemeService.Theme;
            <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ChangeTheme(mode)">
                @mode
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="ChangeAccent" />
</div>

<p>
    Current:
    <strong style="color: @ThemeService.AccentColor;">
        @ThemeService.Theme / @ThemeService.AccentColor
    </strong>
</p>

@code {
    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/theme.js");
        }
    }

    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += HandleThemeChanged;
    }

    private async Task ChangeTheme(ThemeMode mode)
    {
        ThemeService.SetTheme(mode);
        await ApplyViaJs();
    }

    private async Task ChangeAccent(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
        await ApplyViaJs();
    }

    private async Task ApplyViaJs()
    {
        if (_module is not null)
            await _module.InvokeVoidAsync("applyTheme",
                ThemeService.Theme.ToString(), ThemeService.AccentColor);
    }

