// Applies theme attributes to <html> and persists choices in cookies.
// Called from both static SSR (inline script) and interactive components
// via JS interop so the UI updates immediately regardless of render mode.

export function applyTheme(theme, accentColor) {
    const root = document.documentElement;
    root.setAttribute("data-bs-theme", resolveTheme(theme));
    root.style.setProperty("--app-accent", accentColor);
    setCookie("app-theme", theme, 365);
    setCookie("app-accent", accentColor, 365);
}

